const parkCombobox = document.getElementById('park-combobox');
const log = document.getElementById('log');

// nys-input fires on every keystroke. `query` is the typed text, and `value`
// stays the last option you committed.
parkCombobox.addEventListener('nys-input', (e) => {
  log.textContent = `Filtering for "${e.detail.query}"`;
});

// nys-change fires when you choose an option or clear the field.
parkCombobox.addEventListener('nys-change', (e) => {
  log.textContent = e.detail.value
    ? `Selected value: ${e.detail.value}`
    : 'You cleared the selection.';
});
